function lab(id){
 if(id==='cropdoctor')return '<div class="evidence-lab" data-evidence-lab="cropdoctor"><h4>Try a water-balance scenario</h4><p>Illustrative browser calculation: rice, mid stage, loamy soil, ET0 = 5 mm/day, no irrigation. Synthetic inputs; not farming advice or measured outcomes.</p><label>Starting moisture <input data-lab-input="moisture" type="range" min="0" max="100" step="1" value="50"> <output data-lab-value="moisture">50%</output></label><label>Rain <input data-lab-input="rain" type="range" min="0" max="40" step="1" value="10"> <output data-lab-value="rain">10 mm</output></label><p class="lab-result" data-lab-result role="status">Next-day moisture: 52.45% of field capacity.</p></div>';
 if(id==='veritas')return '<div class="evidence-lab" data-evidence-lab="veritas"><h4>Try a constraint</h4><p>Browser interval illustration. The recorded local check above runs the supplied exact-rational Python solver.</p><label>Lower bound: x ≥ <input data-lab-input="lower" type="number" min="0" max="10" step="1" value="3"></label><label>Upper bound: x ≤ <input data-lab-input="upper" type="number" min="0" max="10" step="1" value="2"></label><p class="lab-result" data-lab-result role="status">Contradiction: x cannot be at least 3 and at most 2.</p></div>';
 return '<div class="evidence-lab" data-evidence-lab="nexus"><h4>Try changing a sealed entry</h4><p>Illustrative browser hash chain with three example entries. No public timestamp or external anchoring.</p><button type="button" data-ledger-action="seal">Seal example chain</button><button type="button" data-ledger-action="tamper" disabled>Change sealed text</button><p class="lab-result" data-lab-result role="status">Seal the example, then change its first entry.</p><ol data-lab-chain></ol></div>';
}
function render(project,escape){const r=records[project.id];if(!r)return '';return '<section class="project-evidence"><p class="eyebrow">SOURCE + FOCUSED LOCAL CHECK</p><h3>'+labels[project.id]+'</h3><p>'+escape(r.check)+'</p><div class="evidence-result"><span>PASS · '+r.checked_on+'</span><p>'+escape(r.result)+'</p></div><p class="evidence-limit">'+escape(r.limits)+'</p><details><summary>Inspect the reviewed source</summary><p class="source-path">'+escape(r.source)+'</p><pre><code>'+escape(r.excerpt)+'</code></pre><a href="'+escape(r.download)+'" download>Download excerpt and source fingerprint ↗</a></details>'+lab(project.id)+'</section>';}
function install(){if(typeof document==='undefined')return;const ledgers=new WeakMap();document.addEventListener('input',event=>{const input=event.target.closest?.('[data-lab-input]'),box=input?.closest('[data-evidence-lab]');if(!box)return;const read=name=>box.querySelector('[data-lab-input="'+name+'"]').value,result=box.querySelector('[data-lab-result]');if(box.dataset.evidenceLab==='cropdoctor'){const moisture=read('moisture'),rain=read('rain');box.querySelector('[data-lab-value="moisture"]').textContent=moisture+'%';box.querySelector('[data-lab-value="rain"]').textContent=rain+' mm';result.textContent='Next-day moisture: '+balance(moisture,rain).toFixed(2)+'% of field capacity.';}else{const lower=read('lower'),upper=read('upper');if(lower===''||upper===''){result.textContent='Enter both bounds as integers from 0 to 10.';return;}const b=bounds(lower,upper);result.textContent=b.invalid?'Enter both bounds as integers from 0 to 10.':b.valid?'Satisfiable interval. Example witness: x = '+b.witness+'.':'Contradiction: x cannot be at least '+b.lower+' and at most '+b.upper+'.';}});
 document.addEventListener('click',async event=>{const button=event.target.closest?.('[data-ledger-action]'),box=button?.closest('[data-evidence-lab]');if(!box||button.disabled)return;const result=box.querySelector('[data-lab-result]'),seal=box.querySelector('[data-ledger-action="seal"]'),tamper=box.querySelector('[data-ledger-action="tamper"]');seal.disabled=tamper.disabled=true;try{let entries=ledgers.get(box);if(button.dataset.ledgerAction==='seal'){entries=await chain();ledgers.set(box,entries);}else if(entries)entries[0].core.prediction.decision='Changed after sealing';else throw Error('Seal the example first.');const checked=await verify(entries);result.textContent=checked.valid?'All three entries verify. Now change the sealed text.':'Tampering detected at entry '+(checked.index+1)+': its stored hash no longer matches.';const list=box.querySelector('[data-lab-chain]');list.replaceChildren(...entries.map(e=>{const row=document.createElement('li');row.textContent=e.core.prediction.decision+' · '+e.hash.slice(0,14)+'…';return row;}));tamper.disabled=!checked.valid;}catch(error){result.textContent=error.message;tamper.disabled=true;}finally{seal.disabled=false;}});
}
